r"""Concept questions from Prof. Degen's lecture slides (HS26) as quiz encounters in the solid-state rooms.
Writes game/content/solid-state/slide-quizzes.json (an "extras" file: {items: [{room, enc}]}). Run: python3 build.py
Sources: lecture slides Week01-Week04 (question slides) and "Week08 (Quizzes).pdf" (46 questions on chapters 1-3). The slides
mark the correct option with a red frame; the explanations are ours, written against the script (Script-2026). The two
"Yes or No?" slides (Week01 slide 16, Week02 slide 23) carry no key: those answers are ours and say so.
Options are shuffled by the game, so options never refer to each other by number.
Style rule: no ASCII apostrophes inside r'...' strings (use ’ in text, ^\prime in math)."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
W = {1: 'Week01 (Chapters 1-1 and 1-2).pdf', 2: 'Week02 (Chapters 1-3 to 1-5).pdf', 3: 'Week03 (Chapters 1-6).pdf', 4: 'Week04 (Chapters 2-1 to 2-2).pdf', 8: 'Week08 (Quizzes).pdf'}
F = lambda name, alt, width=None: f'<br><img class="fig" src="content/solid-state/fig/{name}.png" alt="{alt}"' + (f' style="max-width:{width}px"' if width else '') + '>'


def q(week, slide, text, options, correct, explain, own=False):
    src = {'file': f'lecture slides/{W[week]}', 'where': f'slide {slide}' + ('; no key on the slide, the answer is ours' if own else '; the slide marks this answer')}
    return {'q': text, 'options': options, 'correct': correct, 'explain': explain, 'source': src}


yn = lambda week, slide, n, text, yes, explain: q(week, slide, f'Yes or no? {text}', ['Yes', 'No'], 0 if yes else 1, explain, own=True)

LATTICE = [
 yn(1, 16, 1, 'All unit cells possess exactly 1 lattice site.', False, r'Only <b>primitive</b> unit cells do. Conventional cells are often larger: the BCC cube holds 2 lattice points, the FCC cube 4 (script 1.2.1, Fig. 1.2).'),
 yn(1, 16, 2, 'There are infinitely many primitive unit cells.', True, r'Any cell that tiles space under the lattice translations and contains one lattice point is primitive: you can shear the parallelogram as you like (Fig. 1.2), and the Wigner–Seitz cell is one more.'),
 yn(1, 16, 3, 'All primitive unit cells have the same volume.', True, r'Each holds exactly one lattice point, so its volume is (total volume)/(number of lattice points) $=|\mathbf a\cdot(\mathbf b\times\mathbf c)|$, whatever its shape.'),
 yn(1, 16, 4, 'All Bravais lattices are also unit cells.', True, r'The cell drawn for each Bravais lattice (cube, centred cube, hexagonal prism ...) tiles space under lattice translations, so it is a unit cell: the <i>conventional</i> one, chosen to show the symmetry.'),
 yn(1, 16, 5, 'All Bravais lattices are also primitive unit cells.', False, r'The centred ones are not: body-centred, face-centred and base-centred conventional cells contain 2, 4 and 2 lattice points. Their primitive cells are smaller and hide the cubic symmetry.'),
 yn(1, 16, 6, 'All 2D lattices can be assigned to one of the 5 Bravais lattices.', True, r'In 2D there are exactly five: oblique, rectangular, centred rectangular, square, hexagonal (14 in 3D, script 1.2.3). Every lattice falls into one of them by its symmetry.'),
 q(1, 33, 'Which structure is shown?' + F('w1-33-structure', 'Hexagonal prism: atoms on the corners and centres of the two hexagonal faces, and three atoms in a plane halfway between', 220), ['HCP', 'FCC', 'BCC', 'Diamond', 'ZnS', 'None of these'], 0,
   r'Hexagonal layers stacked A B A: a hexagonal lattice with a two-atom basis. The three atoms in the middle plane sit over every second triangle of the layer below. HCP is <b>not</b> a Bravais lattice.'),
 q(1, 34, 'Which structure is shown?' + F('w1-34-structure', 'Cube with one kind of atom on corners and face centres and a second kind inside, each bonded tetrahedrally to four atoms of the first kind', 230), ['HCP', 'FCC', 'BCC', 'Diamond', 'ZnS', 'None of these'], 4,
   r'Two FCC lattices shifted by $(\frac14,\frac14,\frac14)$ along the space diagonal, every atom with four tetrahedral neighbours. Two <b>different</b> atoms: zincblende (ZnS, GaAs). With identical atoms it would be diamond (Si, Ge).'),
 q(1, 35, 'Which structure is shown?' + F('w1-35-structure', 'Cube with atoms on the corners and in the centres of the faces', 230), ['HCP', 'FCC', 'BCC', 'Diamond', 'ZnS', 'None of these'], 1,
   r'Corners plus face centres: face-centred cubic, 4 atoms per cube, 12 nearest neighbours at $a/\sqrt2$.'),
 q(1, 36, 'Which structure has the atomic layering shown?' + F('w1-36-layering', 'Three close-packed layers of spheres labelled A, B and C, each shifted into the hollows of the one below', 240), ['HCP', 'FCC', 'BCC', 'Diamond', 'ZnS', 'None of these'], 1,
   r'Close-packed layers in the sequence A B C A B C are FCC (the layers are its $(111)$ planes). A B A B is HCP. Both fill 74% of space.'),
 q(1, 37, 'Which two-atomic lattice has the highest packing density?', ['HCP', 'FCC', 'BCC', 'ZnS', 'HCP and ZnS', 'It depends on the ionic radii'], 5,
   r'With two kinds of spheres the densest arrangement depends on the ratio of the radii: which structure lets anions and cations touch without the anions overlapping (CsCl for similar radii, NaCl for a smaller cation, ZnS for a much smaller one).'),
 q(1, 38, 'What is the coordination number of an HCP lattice?', ['4', '6', '8', '10', '12', '16', '20'], 4,
   r'6 neighbours in the own close-packed layer, 3 above and 3 below: 12, the same as FCC. That is the maximum for equal spheres.'),
 q(1, 39, 'What is the number of atoms per (conventional) unit cell in a BCC lattice?', ['1', '2', '3', '4', '6', '8'], 1,
   r'$8\times\frac18$ from the corners plus 1 in the centre: 2. The primitive cell therefore has volume $a^3/2$ (sheet 2 Q1).'),
]

RECIPROCAL = [
 q(2, 51, 'Which reciprocal lattice belongs to the direct lattice shown?' + F('w2-51-reciprocal-candidates', 'Direct lattice: an oblique cell with a horizontal and b leaning to the upper left. Four candidates: 1 rectangular, 2 oblique with b star vertical and a star leaning up to the right, 3 oblique with a star horizontal, 4 a 60 degree rhombus'), ['Panel 1', 'Panel 2', 'Panel 3', 'Panel 4'], 1,
   r'$\mathbf a^*\perp\mathbf b$ and $\mathbf b^*\perp\mathbf a$ (script eq. 1.8: $\mathbf a^*\cdot\mathbf b=0$). $\mathbf a$ is horizontal, so $\mathbf b^*$ must be vertical; $\mathbf b$ leans to the left, so $\mathbf a^*$ is tilted upwards. Only panel 2 has both.'),
 q(2, 52, 'Which reciprocal lattice belongs to the direct lattice shown (a and b enclose 120°)?' + F('w2-52-reciprocal-candidates', 'Direct lattice: rhombic cell with 120 degrees between a and b. Four candidates: 1 rectangular, 2 oblique, 3 oblique, 4 a rhombus with 60 degrees between a star and b star'), ['Panel 1', 'Panel 2', 'Panel 3', 'Panel 4'], 3,
   r'The reciprocal of a hexagonal lattice is hexagonal again, rotated by 30°. With 120° between $\mathbf a$ and $\mathbf b$, the vectors $\mathbf a^*\perp\mathbf b$ and $\mathbf b^*\perp\mathbf a$ enclose 60°.'),
 q(2, 53, 'What is the Miller index of the lattice plane?' + F('w2-53-miller-plane', 'Cube with axes a, b, c. The shaded plane contains the origin, the point (1/2, 1, 0) and the point (0, 1, 1/2)', 260), [r'$(1,\frac12,\frac12)$', r'$(1,\frac12,-\frac12)$', r'$(2,1,1)$', r'$(-2,1,1)$', r'$(2,-1,2)$', r'$(2,-1,-1)$', r'$(1,2,2)$', r'$(1,-2,2)$'], 4,
   r'The plane contains the origin and the points $(\frac12,1,0)$ and $(0,1,\frac12)$, so its normal $(h,k,l)$ obeys $\frac h2+k=0$ and $k+\frac l2=0$: $(hkl)\propto(2,-1,2)$. Check with the neighbouring plane of the family, $2x-y+2z=1$: intercepts $\frac12$, $-1$, $\frac12$, reciprocals $2,-1,2$. A plane through the origin has no intercepts: always shift to a parallel one.'),
 q(8, 2, 'A hexagonal lattice in direct space with $a_1=a_2=1$ Å. What is the volume (area) of the first Brillouin zone?' + F('q02-hex-lattice', 'Hexagonal lattice of points with primitive vectors a1 and a2 enclosing 60 degrees', 180), [r'$4\pi^2$ Å$^{-2}$', r'$8\pi^2/\sqrt3$ Å$^{2}$', r'$8\pi^2/\sqrt3$ Å$^{-2}$', r'$8\pi^2$ Å$^{-2}$'], 2,
   r'Every primitive cell of the reciprocal lattice has the area $(2\pi)^2/A_{\rm cell}$ (sheet 1 Q3c in 2D). $A_{\rm cell}=a^2\sin60^\circ=\frac{\sqrt3}{2}$ Å$^2$, so $A_{BZ}=\frac{4\pi^2}{\sqrt3/2}=\frac{8\pi^2}{\sqrt3}$ Å$^{-2}$. Units: inverse area.'),
 q(8, 4, 'A two-dimensional lattice with rotational symmetry and a single lattice constant $a$. Which statement is correct?', ['The two reciprocal lattice vectors do not necessarily have the same length', r'The volume of the first Brillouin zone is $1/a^2$', r'To compute the structure factor, only atoms closer than $a$ need to be considered', 'The angle between the basis vectors is 60°, 90° or 120°'], 3,
   r'One lattice constant plus a rotation axis means square (90°) or hexagonal (60° or 120°, the same lattice). Then $|\mathbf a^*|=|\mathbf b^*|$; the zone area is $(2\pi)^2/A_{\rm cell}$, not $1/a^2$; and the structure factor sums over all atoms of the basis in one cell.'),
 q(8, 8, r'A lattice with the unit vectors $(a,0,0)$, $(0,a,0)$ and $(\frac a2,\frac a2,\frac a2)$. Which statement is correct?', ['The reciprocal lattice vectors are orthogonal', 'The unit vectors describe a two-atomic basis', 'The lattice is a body-centred cubic (BCC) Bravais lattice', 'Each lattice site is occupied by one atom'], 2,
   r'$2\mathbf a_3-\mathbf a_1-\mathbf a_2=(0,0,a)$: the vectors generate all cube corners and, with $\mathbf a_3$, all body centres: BCC. Lattice vectors say nothing about the basis or how many atoms sit on a site, and the reciprocal vectors (an FCC set) are not orthogonal.'),
 q(8, 11, 'Given an FCC direct lattice, what is its reciprocal lattice?', ['FCC', 'BCC', 'SC', 'Hexagonal'], 1, r'FCC and BCC are reciprocal to each other (sheet 2 Q1): FCC with cube edge $a$ gives BCC with cube edge $4\pi/a$. Its first Brillouin zone is the truncated octahedron.'),
 q(8, 12, 'Given a BCC direct lattice, what is its reciprocal lattice?', ['FCC', 'BCC', 'SC', 'Hexagonal'], 0, r'$\mathbf b_1=\frac{2\pi}{a}(\hat{\mathbf y}+\hat{\mathbf z})$ and cyclic: an FCC lattice with cube edge $4\pi/a$ (sheet 2 Q1). First Brillouin zone: rhombic dodecahedron.'),
 q(8, 13, 'Given a SC direct lattice, what is its reciprocal lattice?', ['FCC', 'BCC', 'SC', 'Hexagonal'], 2, r'Orthogonal vectors of equal length stay orthogonal and equal: simple cubic with lattice constant $2\pi/a$. The first Brillouin zone is a cube.'),
 q(8, 14, 'Given a hexagonal direct lattice, what is its reciprocal lattice?', ['FCC', 'BCC', 'SC', 'Hexagonal'], 3, r'Hexagonal again, rotated by 30° about the $c$ axis, with in-plane constant $\frac{4\pi}{\sqrt3a}$ and $2\pi/c$ along the axis.'),
 q(8, 16, r'An FCC lattice with cube edge $a_0$. What is the volume of the primitive unit cell?', [r'$a_0^3$', r'$a_0^3/2$', r'$a_0^3/4$', r'$a_0^3/8$'], 2, r'The cube contains $8\times\frac18+6\times\frac12=4$ lattice points, and a primitive cell contains one: $a_0^3/4$.'),
]

DIFFRACTION = [
 yn(2, 23, 1, r'$\lambda=2d_{hkl}\sin\theta$. The Bragg condition can be fulfilled for any wavelength $\lambda$.', False, r'$\sin\theta\le1$ requires $\lambda\le2d_{hkl}$. For $\lambda$ larger than twice the largest plane spacing there is no Bragg peak at all: this is why visible light is not diffracted by crystals and why cold neutrons pass through a beryllium filter.'),
 yn(2, 23, 2, r'The larger the indices $hkl$, the larger the distance $d_{hkl}$.', False, r'The other way round: $d_{hkl}=2\pi/|\mathbf G_{hkl}|$, cubic $d=a/\sqrt{h^2+k^2+l^2}$. High indices are closely spaced planes and scatter to large angles.'),
 yn(2, 23, 3, r'Given a fixed wavelength $\lambda$, there is only a finite number of Bragg peaks.', True, r'$|\mathbf G|=\frac{4\pi}{\lambda}\sin\theta\le\frac{4\pi}{\lambda}$: only the reciprocal lattice points inside a sphere of radius $4\pi/\lambda$ can be reached (calculation fight "How many spots can the detector ever see?").'),
 yn(2, 23, 4, r'For a given pair $(\lambda,\theta)$ there can be at most a single Bragg peak.', False, r'$(\lambda,\theta)$ fixes only $d$. Several plane families can share one spacing: symmetry-equivalent ones such as $(100),(010),(001)$, or accidental ones such as $(300)$ and $(221)$ in a cubic crystal ($h^2+k^2+l^2=9$ for both). In a powder they fall on the same ring.'),
 q(2, 54, 'A neutron scattering experiment on a BCC lattice measures a Bragg peak at (100). What can we conclude?' + F('w2-54-neutron-bcc', 'Two neutron diffraction scans against Bragg angle: the upper one shows a small (100) peak (arrow) besides the strong (110) peak, the lower one only (110)', 260), ['The lattice consists of a single atomic species', 'The lattice consists of two atomic species', 'The lattice is rectangular', 'The lattice has an inversion symmetry', 'Friedel’s law does not apply'], 1,
   r'For identical atoms $F=f(1+e^{i\pi(h+k+l)})=0$ at $(100)$. With different scattering lengths on corner and centre, $F=f_1-f_2\ne0$: the peak appears, weakly (sheet 3 Q1c). The crystal is then really simple cubic with a two-atom basis (CsCl type, e.g. an ordered alloy).'),
 q(2, 55, 'What scatters X-rays most strongly?', ['The atomic nucleus', 'Atomic nuclei that are magnetic', 'The inner (core) electrons', 'The outer (valence) electrons'], 2,
   r'X-rays scatter off the electron charge density (Thomson scattering $\propto1/m^2$, so nuclei are negligible). Most electrons of an atom are core electrons, concentrated near the nucleus: the form factor $f(\mathbf q)$ grows with $Z$. Neutrons see the nuclei (and magnetic moments) instead.'),
 q(2, 56, 'An X-ray beam on a cubic crystal powder gives a powder diffraction pattern. Which statement is <u>wrong</u>?', ['Rotating the sample changes the diffraction pattern', 'A ring can contain contributions from several lattice planes, such as (100), (010) and (001)', 'The pattern allows determining both the lattice type and the cell constant', r'For a given wavelength $\lambda$, several rings can appear'], 0,
   r'A powder contains crystallites in all orientations, so rotating it changes nothing: every $\mathbf G$ with $|\mathbf G|\le4\pi/\lambda$ is in reflection position for some grains and gives a ring (script 1.5.4). The ring radii give $d_{hkl}$, their sequence the lattice type (sheet 3 Q1).'),
 q(8, 3, 'X-rays are directed at a single crystal with monoclinic symmetry. What happens?', ['The diffraction pattern changes as the crystal is rotated', 'For this crystal it is impossible to draw any conclusions on the structure from X-ray diffraction', 'With monochromatic X-rays the diffraction pattern shows rings', r'Each $hkl$ plane generates one Bragg peak'], 0,
   r'A single crystal has one orientation: a reflection appears only when $\mathbf k^\prime-\mathbf k=\mathbf G$ is met, so turning the crystal moves reciprocal lattice points through the Ewald sphere and the spots change. Rings need a powder. Low symmetry does not prevent structure determination.'),
 q(8, 6, r'The powder pattern of sodium was measured at two temperatures $T_1$ (red, dotted) and $T_2$ (blue). The lattice expands on heating. Which statement is correct?' + F('q06-sodium-two-temperatures', 'Powder pattern, relative intensity against 2 theta: peaks (110), (200), (211); the red dotted T1 peaks lie at slightly larger angles than the blue T2 peaks'), [r'$T_1>T_2$', r'$T_1<T_2$', r'$T_1=T_2$', r'Sodium has a phase transition between $T_1$ and $T_2$'], 1,
   r'The $T_1$ peaks sit at larger $2\theta$. Bragg: $\sin\theta=\lambda/2d$, larger angle means smaller $d$, a smaller lattice constant, hence the colder sample: $T_1<T_2$. The same three peaks appear in both, so the structure (BCC: $h+k+l$ even) is unchanged.'),
 q(8, 7, r'We measure several Bragg peaks $(hkl)$ with X-rays. Which concept describes their different intensities?', ['The Bragg condition', 'The size of the Brillouin zone', 'The Bravais lattice', 'The structure factor'], 3,
   r'The lattice (Bragg or Laue condition) fixes <i>where</i> peaks can be; the basis fixes <i>how strong</i> they are: $I\propto|F(\mathbf G)|^2$, $F=\sum_jf_je^{i\mathbf G\cdot\mathbf r_j}$ (script 1.5.2, eq. 1.23).'),
 q(8, 17, 'Which statement is <u>wrong</u>?', ['The symmetries of a crystal and of its diffraction pattern are identical', 'Diffraction peaks can only appear if the Bragg condition is fulfilled', r'The basis vector $\vec a^*$ of the reciprocal lattice is orthogonal to the basis vectors $\vec b$ and $\vec c$ of the direct lattice', 'The larger a crystal, the stronger the intensity of a Bragg peak'], 0,
   r'The pattern shows $I\propto|F(\mathbf G)|^2$ and $|F(-\mathbf G)|=|F(\mathbf G)|$ (Friedel): it always has inversion symmetry, even if the crystal has none, and the phases are lost (script 1.5.3). The other three hold: $\vec a^*\propto\vec b\times\vec c$, and the peak intensity grows with the number of cells.'),
]

BONDING = [
 q(3, 32, r'$H=-\frac{\hbar^2\nabla^2}{2m}-\frac{e^2}{4\pi\epsilon_0r_A}-\frac{e^2}{4\pi\epsilon_0r_B}+\frac{e^2}{4\pi\epsilon_0R}$ describes the H$_2^+$ molecule (electron at distances $r_A,r_B$ from the nuclei A and B, which are $R$ apart). Which aspect is <u>neglected</u>?', ['Coulomb repulsion between the nuclei', 'Kinetic energy of the nuclei', 'Coulomb attraction between the electron and the nuclei', 'Electrostatic potential of the electron', 'Electrostatic screening of the positive nuclear charges by the electron'], 1,
   r'There is no $-\frac{\hbar^2}{2M}\nabla_{A,B}^2$: the nuclei are treated as fixed at distance $R$ (Born–Oppenheimer: $M\gg m$). $R$ is a parameter, and the electronic energy $E(R)$ becomes the potential in which the nuclei move (script 1.6.4).'),
 q(3, 33, 'Metallic bonding. Which statement is <u>wrong</u>?', ['The valence electrons can move freely between the atomic cores', 'The metallic bond has no preferential orientation', 'Metals are primarily FCC or HCP because this maximises the filling factor', 'All electrons are strongly localised at the atomic sites'], 3,
   r'The valence electrons are delocalised over the whole crystal: spreading out lowers their kinetic energy, and that gain is the bond (script 1.6.6). Only the core electrons stay localised. Because the bond is not directional, metals prefer close packing.'),
 q(3, 34, 'List the solids in order of increasing cohesive energy per atom.', ['Diamond, NaCl, Na, Ar', 'Na, Ar, diamond, NaCl', 'NaCl, Ar, Na, diamond', 'Ar, Na, NaCl, diamond'], 3,
   r'Van der Waals $<$ metallic $<$ ionic $<$ covalent: Ar $\approx0.08$, Na $\approx1.1$, NaCl $\approx3.3$, diamond $\approx7.4$ eV per atom (values from the slide; script Table 1.2 and 1.6.7).'),
 q(8, 5, 'Which chemical bonding type is present in <i>any</i> material?', ['Metallic bonding', 'Van der Waals bonding', 'Hydrogen bonds', 'Covalent bonds', 'All of these equally'], 1,
   r'Fluctuating dipoles exist in every atom, so the $-1/r^6$ attraction is always there (script 1.6.1). It is usually hidden behind much stronger bonds and only decides the structure where nothing else acts: noble gases, between molecules, between graphene layers.'),
 q(8, 9, 'Four configurations of atomic orbitals. Which do <u>not</u> lead to a covalent bond?' + F('q09-orbital-configurations', 'A: two parallel p orbitals side by side. B: a p orbital perpendicular to the bond axis next to a p orbital along the axis. C: a d orbital next to a parallel p orbital. D: an s orbital overlapping two lobes of opposite sign of a d orbital'), ['A, B and C', 'B, C and D', 'B and D', 'All configurations lead to covalent bonds'], 2,
   r'A bond needs a non-zero overlap (hopping) integral. In B and D the positive and negative lobes of one orbital overlap equally with the other orbital and the contributions cancel by symmetry. A (two parallel p: a $\pi$ bond) and C (d and p with matching lobe signs) have a net overlap.'),
 q(8, 10, r'The H$_2^+$ molecule forms a bonding and an anti-bonding molecular orbital. Which statement is correct?', ['In the anti-bonding orbital the electron has a higher probability density between the nuclei than in the bonding orbital', 'The anti-bonding level has a lower energy than the bonding level', 'The wave function of the anti-bonding orbital is antisymmetric', r'The chemical bond of the H$_2^+$ molecule is called a hydrogen bond'], 2,
   r'Anti-bonding: $\psi_A-\psi_B$, antisymmetric with a node halfway, little charge between the nuclei, energy $E_0+t$. Bonding: $\psi_A+\psi_B$, charge piled up between the nuclei, energy $E_0-t$ (sheet 3 Q3). The bond is covalent; a hydrogen bond is something else (a proton shared between two electronegative atoms, script 1.6.5).'),
 q(8, 15, 'Which orbitals are involved in the graphene carbon–carbon bonds?', [r'sp', r'sp$^2$', r'sp$^3$', 'None of these'], 1,
   r'Three sp$^2$ hybrids at 120° in the plane form the $\sigma$ bonds of the honeycomb; the remaining p$_z$ orbital forms the $\pi$ band, which gives the linear dispersion of sheet 6 Q2. sp$^3$ (four tetrahedral bonds) is diamond.'),
]

PHONONS = [
 q(4, 34, r'Normal modes of a simple cubic lattice with one atom per cell. Which statement about the wave vector $\vec q$ is correct?', [r'Only this: $q$ can assume $N$ different values, $N$ being the number of unit cells', r'$q$ can assume any value', r'Only this: $q$ is confined to $(-\pi/a,\pi/a]$, $a$ being the lattice constant', r'The smallest value of $q$ $(>0)$ is $2\pi/a$', r'Both: $q$ takes $N$ values, and they lie in $(-\pi/a,\pi/a]$'], 4,
   r'Periodic boundary conditions: $q=\frac{2\pi}{Na}p$, spacing $2\pi/L$. Values outside the first Brillouin zone repeat the same displacements, so exactly $N$ distinct $q$ remain (sheet 4 Q1b; script 2.2.4). The smallest positive one is $2\pi/L$, not $2\pi/a$.'),
 q(8, 19, 'The Debye temperature is approximately proportional to ...', ['the Fermi temperature', 'the density of states', 'the velocity of sound', 'the number of valence electrons'], 2,
   r'$k_BT_D=\hbar\omega_D=\hbar v_sk_D$ with $k_D=(6\pi^2n)^{1/3}$ fixed by the density of atoms. Stiff, light crystals (diamond: 2230 K) have a high sound velocity and a high $T_D$; soft, heavy ones (lead: 105 K) a low one.'),
 q(8, 20, 'Silicon: two FCC lattices shifted by ¼ of the space diagonal. How many phonon branches are expected?', ['3 acoustic', '3 acoustic, 3 optical', '6 acoustic', '6 optical', r'3 acoustic, $7\times3$ optical', r'$8\times3$ acoustic'], 1,
   r'Count atoms in the <b>primitive</b> cell: 2 (the cube with 8 atoms is not primitive). $3\times2=6$ branches, always 3 acoustic, the remaining $3(p-1)=3$ optical (script 2.2.6).'),
 q(8, 21, 'Which model is most suited to describe optical lattice modes?', ['Band model', 'Debye model', 'Einstein model', 'Tight-binding model'], 2,
   r'Optical branches are nearly flat, $\omega(q)\approx\omega_E$: one frequency for all modes is exactly Einstein’s assumption (sheet 4 Q2). Debye ($\omega=v_sq$) describes the acoustic branches.'),
 q(8, 22, 'Which phenomenon is <u>incompatible</u> with the harmonic approximation of lattice dynamics?', ['Phonon decay', 'Electron–electron interactions', r'The specific heat approaches $C_V=3k_BN$ in the Dulong–Petit regime', 'All of these'], 0,
   r'In the harmonic crystal the normal modes are exact eigenstates: phonons never interact and live forever. Decay, thermal expansion and a finite thermal conductivity need the cubic and higher terms (script 2.3.3). Dulong–Petit <i>is</i> the harmonic result, and electron–electron interaction has nothing to do with it.'),
 q(8, 23, r'Diatomic chain with masses $M_1$, $M_2$ and spring constant $f$ (the slides’ letter; the script calls it $k$, and writes the wave vector $q$). Which point 1–4 of the dispersion matches the mode shown (displacements drawn sideways)?' + F('q23-diatomic-mode', 'Left: dispersion with acoustic and optical branch; points 1 (acoustic) and 3 (optical) at k = pi over 2a, point 2 (optical, small k), point 4 (acoustic, near pi over a). Right: displacement pattern of the chain over four lattice constants; filled and open atoms lie on two sine curves of opposite sign with wavelength 4a'), ['Point 1', 'Point 2', 'Point 3', 'Point 4'], 2,
   r'The two kinds of atoms move against each other (the open circles are displaced opposite to the filled ones): optical branch. The pattern repeats after $4a$: $k=\frac{2\pi}{4a}=\frac{\pi}{2a}$. Optical branch at $\pi/2a$ is point 3.'),
 q(8, 24, r'Diatomic chain. Which assignment between the modes (1)–(4) and the points A–D of the dispersion is correct?' + F('q24-diatomic-modes', 'Four snapshots of a chain of heavy and light atoms. (1) no relative motion. (2) heavy atoms move left, light atoms right, the same in every cell. (3) heavy atoms at rest, neighbouring light atoms move in opposite directions. (4) light atoms at rest, neighbouring heavy atoms move in opposite directions. Dispersion: A optical at k = 0, B optical at the zone boundary, C acoustic at the zone boundary, D acoustic at k = 0'), ['(A1), (B4), (C3), (D2)', '(A2), (B3), (C4), (D1)', '(A1), (B3), (C4), (D2)', '(A2), (B4), (C3), (D1)', '(A4), (B2), (C3), (D1)', '(A4), (B2), (C1), (D3)'], 1,
   r'(Slide notation: $k$ is the wave vector, $f$ the spring constant; in the script $q$ and $k$.) D (acoustic, $k=0$): all atoms move together, a rigid shift: (1). A (optical, $k=0$): the two sublattices move against each other, identically in every cell: (2). At the zone boundary neighbouring cells are in antiphase and one sublattice stands still: in the optical mode B the light atoms move, $\omega^2=2f/M_{\rm light}$: (3); in the acoustic mode C the heavy atoms move, $\omega^2=2f/M_{\rm heavy}$: (4) (script 2.2.5).'),
 q(8, 25, 'X-rays are inelastically scattered off a crystal. Upon scattering, the lattice vibrations change ...', ['only their amplitude', 'only their wavelength', 'only their frequency', 'wavelength and frequency', 'amplitude, wavelength and frequency', 'none of these'], 4,
   r'Inelastic means a phonon $(\mathbf q,\omega)$ is created or absorbed: $\hbar\omega=E_i-E_f$, $\mathbf q=\mathbf k_i-\mathbf k_f+\mathbf G$ (script 2.3.2). One mode gains or loses a quantum: its amplitude changes, and with it which wavelengths and frequencies are present in the motion of the lattice.'),
 q(8, 26, r'A lattice with optical and acoustic modes, two atom types with masses $M_1$ and $M_2>2M_1$. How can we increase the energy gap at the edge of the Brillouin zone?', [r'By doubling $M_1$ (light mass)', r'By doubling $M_2$ (heavy mass)', r'By doubling $M_1$ and $M_2$', 'By increasing the distance between atoms, leading to a weaker spring force'], 1,
   r'Notation of the slides: $f$ is the spring (force) constant between neighbours, $k$ the wave vector; the script writes the spring constant $k$ and the wave vector $q$. At the zone edge $\omega_{\rm opt}=\sqrt{2f/M_1}$, $\omega_{\rm ac}=\sqrt{2f/M_2}$ (light mass $M_1$ in the optical mode, heavy $M_2$ in the acoustic one). A heavier $M_2$ lowers the acoustic edge: the gap grows. A heavier $M_1$ lowers the optical edge: the gap shrinks. Doubling both, or weakening $f$, scales both frequencies down and the gap with them.'),
 q(8, 27, 'Phonon dispersion of a one-dimensional chain. Which segment has the highest phonon density of states?' + F('q27-chain-dos-segments', 'A curve omega(q) with a minimum at q = 0, rising to both sides. Three frequency intervals of equal height are marked: a) at the bottom, where the curve is flat, b) in the middle, c) at the top, where the curve is steep', 260), ['Segment A', 'Segment B', 'Segment C', 'All segments have the same DoS'], 0,
   r'In 1D the $q$ values are equally spaced, so the number of modes per frequency interval is $g(\omega)\propto1/|d\omega/dq|$. Where the curve is flat (segment a, at the extremum) the most $q$ values fall into the same $\Delta\omega$: a van Hove singularity (script 2.4.2).'),
 q(8, 28, 'Which of the following applies to optical modes of lattice vibrations?', ['Only this: they can be excited by electromagnetic waves', r'Only this: their frequency does not approach zero for $q\to0$, $\omega(q=0)\ne0$', r'Both: they can be excited by electromagnetic waves, and $\omega(q=0)\ne0$', 'Neither of the two'], 1,
   r'$\omega(q\to0)\ne0$ is what defines an optical branch: the atoms of the basis move against each other. Coupling to light needs in addition that this motion carries an oscillating dipole, i.e. differently charged atoms (NaCl: yes; silicon or diamond: no). So "excited by light" is not true in general.'),
 q(8, 29, r'Diatomic chain with masses $M>m$. What is the motion of the masses at point P (top branch, zone boundary)?' + F('q29-dispersion-point-p', 'Dispersion with a lower and an upper branch; P is on the upper branch at q = pi over a', 240) + F('q29-motions', 'Five motion patterns of alternating large (M) and small (m) masses: 1 only the large ones move, all to the right. 2 only the small ones move, all to the right. 3 only the large ones move, alternately right and left. 4 only the small ones move, alternately right and left. 5 large ones right, small ones left', 360), ['Pattern 1', 'Pattern 2', 'Pattern 3', 'Pattern 4', 'Pattern 5'], 3,
   r'P is the optical branch at the zone boundary: $\omega^2=2f/m$, only the light masses move, and with $q=\pi/a$ neighbouring cells are in antiphase: pattern 4. Pattern 3 is the acoustic branch at the zone boundary, pattern 5 the optical mode at $q=0$, patterns 1 and 2 are not normal modes.'),
]

ELECTRONS = [
 q(8, 31, 'How does the specific heat of a free electron gas scale with temperature?', ['It is independent of temperature', r'Linear ($\propto T$)', r'Quadratic ($\propto T^2$)', r'Cubic ($\propto T^3$)', r'With the fifth power ($\propto T^5$)', 'It depends on the temperature range'], 1,
   r'Only electrons within $\sim k_BT$ of $\epsilon_F$ can be excited: a fraction $T/T_F$, each gaining $\sim k_BT$. $C_{el}=\frac{\pi^2}{2}Nk_B\frac{T}{T_F}=\gamma T$ (script 3.1.4), valid for all $T\ll T_F$, i.e. for every solid metal.'),
 q(8, 32, 'How does the specific heat of a phonon lattice scale with temperature?', ['It is independent of temperature', r'Linear ($\propto T$)', r'Quadratic ($\propto T^2$)', r'Cubic ($\propto T^3$)', r'With the fifth power ($\propto T^5$)', 'It depends on the temperature range'], 5,
   r'$T\ll T_D$: $C\propto T^3$ (Debye). $T\gg T_D$: constant, $3Nk_B$ (Dulong–Petit). In between neither (script 2.4.3). So in a metal at low $T$: $C=\gamma T+\beta T^3$.'),
 q(8, 33, 'What is the dominant contribution to the specific heat of a solid at room temperature?', ['The free electrons', 'All phonons', 'The acoustic phonons', 'The optical phonons'], 1,
   r'Room temperature is of the order of $T_D$ for most solids, so all phonon branches are excited and give close to $3k_B$ per atom. The electrons add only $\sim\frac{\pi^2}{2}\frac{T}{T_F}k_B\approx1\%$ of that, because $T_F\sim5\times10^4$ K.'),
 q(8, 34, r'An ideal electron gas in a box with $N_e$ electrons (neglect spin). How many electronic states does the crystal have?', [r'Exactly $N_e$ states', r'More than $N_e$ states, but a finite number', 'An infinite number of states', 'None of these'], 1,
   r'Key of the slide. The occupied states are the $N_e$ lowest $\mathbf k$ points inside the Fermi sphere; more states lie above $\epsilon_F$ (otherwise nothing could be excited). In a real crystal the count is finite: each band holds $N$ values of $\mathbf k$ (one per unit cell), and there is one band per atomic orbital. For the idealised box alone one could argue "infinite" (no upper limit on $k$): if this comes up, ask how the lecturer wants it read.'),
 q(8, 35, 'The wave functions of an ideal electron in a box are ...', [r'plane waves (any $k$ allowed)', r'plane waves (only a discrete number of $k$ allowed)', 'a superposition of plane waves', 'plane waves that obey the translational symmetry of the crystal'], 1,
   r'$\psi_{\mathbf k}=\frac{1}{\sqrt V}e^{i\mathbf k\cdot\mathbf r}$ with periodic boundary conditions: $k_i=\frac{2\pi}{L}n_i$ (script 3.1.1). No lattice enters the free-electron model, so there is no crystal symmetry to obey; superpositions of plane waves (Bloch waves) only appear with a periodic potential.'),
 q(8, 39, r'Which density of states $\nu(\epsilon)$ agrees best with the three-dimensional quasi-free electron model?' + F('q39-dos-candidates', 'Five sketches of the density of states against energy: 1 falling steps, 2 constant, 3 rising like a square root, 4 falling smoothly, 5 separate falling spikes'), ['Sketch 1', 'Sketch 2', 'Sketch 3', 'Sketch 4', 'Sketch 5'], 2,
   r'3D free electrons: $\nu(\epsilon)\propto\sqrt\epsilon$ (script 3.1.2). Constant is 2D, $\propto1/\sqrt\epsilon$ is 1D (sheet 6 Q1).'),
 q(8, 47, 'A "free-electron gas" ...', ['is best approximated by the tight-binding model', 'exhibits band gaps, that is, energies for which there are no electronic states', r'at $T=0$ has zero probability of having electrons with energies higher than the Fermi energy $\epsilon_F$', 'has an infinite number of energy bands'], 2,
   r'At $T=0$ the Fermi–Dirac distribution is a step: every state below $\epsilon_F$ full, every state above empty. Gaps and bands need a periodic potential; tight binding is the opposite limit (strongly bound electrons).'),
 q(8, 48, 'What is a typical value for the Fermi temperature?', [r'$T_F\sim0.5$ K', r'$T_F\sim500$ K', r'$T_F\sim5000$ K', r'$T_F\sim50\,000$ K'], 3,
   r'$\epsilon_F$ of a metal is a few eV (Na 3.2 eV, Cu 7 eV) and 1 eV corresponds to 11 600 K: $T_F\sim4$–$8\times10^4$ K. Hence the electron gas is degenerate at any temperature at which the metal is solid.'),
 q(8, 49, r'Order the temperatures as they typically occur for metals: Fermi temperature $T_F$, Debye temperature $T_D$, melting point $T_S$.', [r'$T_F<T_D<T_S$', r'$T_D<T_F<T_S$', r'$T_D<T_S<T_F$', r'$T_S<T_D<T_F$'], 2,
   r'$T_D\sim100$–$500$ K, $T_S\sim10^3$ K, $T_F\sim5\times10^4$ K. Example copper: 343 K, 1358 K, 81 600 K. Consequences: at room temperature the lattice is nearly classical, the electrons are deeply degenerate.'),
]

BANDS = [
 q(8, 36, 'In the nearly-free electron model a band gap is expected at the Brillouin zone boundary. As a consequence ...', ['this model can only be used to describe insulators', 'the material is a metal', 'the electrical conductivity is low', 'none of these follows'], 3,
   r'A gap alone decides nothing: what matters is where the Fermi level lies. A partly filled band gives a metal, completely filled bands an insulator or semiconductor (script 3.2.4). The same model describes both.'),
 q(8, 37, r'A three-dimensional crystal with $N$ unit cells and $m$ atoms per unit cell; each atom has two valence electrons. How many discrete values are allowed for the electron wave vector $\vec k$?', [r'$N$', r'$mN$', r'$2mN$', r'$3mN$'], 0,
   r'The number of $\mathbf k$ values in the first Brillouin zone equals the number of unit cells, whatever sits in the cell (script 3.2.1). More atoms or electrons per cell mean more bands, not more $\mathbf k$ values. Each band then holds $2N$ electrons.'),
 q(8, 38, 'Which band structure (1–4) matches the density of states shown at the top right?' + F('q38-bands-and-dos', 'Four band structures (energy minus Fermi energy from -4 to 8 eV along a path through the Brillouin zone) and one density of states: low and smooth from -4 to 0 eV, a group of tall sharp peaks between 0 and 4 eV, lower above'), ['Band structure 1', 'Band structure 2', 'Band structure 3', 'Band structure 4'], 0,
   r'Read the density of states as "how much band per energy slice": flat bands give peaks, steep bands little weight. The DoS has one smooth, low contribution from $-4$ to 0 eV (a single steep, free-electron-like band) and tall peaks between 0 and 4 eV (several flat bands crowded there). That is panel 1.'),
 q(8, 40, 'Six sketched dispersion relations. Which one fits <b>nearly-free electrons</b>?' + F('q40-dispersions', 'Six hand-drawn dispersions between the zone boundaries. 1: a lower branch starting linearly from zero and an upper, nearly flat branch. 2: similar, but the lower branch starts with a rounded minimum. 3: a lower parabola from zero and an upper band curving down from a maximum at the centre, with gaps at the zone boundary. 4 and 5: cosine-shaped bands. 6: a flat line and a straight V'), ['Sketch 1', 'Sketch 2', 'Sketch 3', 'Sketch 4', 'Sketch 6'], 2,
   r'Nearly free: the free parabola $\hbar^2k^2/2m$ folded into the first zone, with gaps opened where the branches meet at the zone boundary (script 3.2.2). Key of the slide for the rest: tight binding 4 and 5 (cosine bands), phonons 1 (acoustic branch linear at small $k$ plus optical branch), Debye/Einstein approximation 6 (straight line plus constant), free electrons: none, and sketch 2 fits none of the models.'),
 q(8, 40, 'Same six sketches. Which one shows phonons in the <b>Debye / Einstein approximation</b>?' + F('q40-dispersions', 'Six hand-drawn dispersions between the zone boundaries; number 6 consists of a horizontal line and a straight V starting at zero'), ['Sketch 1', 'Sketch 3', 'Sketch 4', 'Sketch 5', 'Sketch 6'], 4,
   r'Debye replaces the acoustic branch by the straight line $\omega=v_s|k|$, Einstein the optical branch by a constant $\omega_E$: sketch 6. Sketch 1 is the real diatomic chain (sine-like acoustic branch, weakly dispersing optical branch).'),
 q(8, 41, 'The electronic density of states ...', ['is large for cold electrons', 'is small at the zone boundary', 'is large at the zone boundary', 'becomes large at very high temperatures'], 2,
   r'At the zone boundary the bands flatten (zero slope, standing waves), so many $\mathbf k$ states share nearly the same energy: van Hove singularities. The density of states is a property of the band structure and does not depend on temperature.'),
 q(8, 42, r'Nearly-free electrons in 1D, atoms at $x=na$. What is the approximate wave function at the boundary of the first Brillouin zone ($k_{BZ}=\pi/a$) in the lowest-energy configuration?', [r'$\Psi(x)\sim\sin(k_{BZ}x)$', r'$\Psi(x)\sim\cos(k_{BZ}x)$', r'$\Psi(x)\sim\exp(ik_{BZ}x)$', 'None of these'], 1,
   r'At the zone boundary $e^{i\pi x/a}$ and $e^{-i\pi x/a}$ are degenerate and mix into standing waves. $|\cos(\pi x/a)|^2$ piles the electron up <b>on</b> the ions at $x=na$, where the potential is attractive: lower energy. $\sin$ puts it between the ions: higher energy. The difference is the gap $2|U_G|$ (script 3.2.2).'),
 q(8, 43, r'Nearly-free electrons, a BCC lattice with a one-atom basis, one valence electron per atom, $T=0$. Which statement is correct?', ['The material is an insulator, because the highest energy level is completely filled', 'If the highest electron bands overlap, the material is a metal; otherwise it is a semiconductor', 'The material is a metal, because the highest band cannot be completely filled', 'The material is a semiconductor'], 2,
   r'One atom per primitive cell and one electron per atom: $N$ electrons for a band that holds $2N$ (spin). The band is half full, the Fermi surface lies inside the first zone: a metal, no matter how large the gaps are. This is sodium (sheet 7 Q2).'),
 q(8, 44, 'Which statement concerning the tight-binding model is correct?', ['Different energy bands never overlap', 'Weakly bound electrons have narrower energy bands', 'Energy bands get wider with increasing overlap between atomic orbitals', 'The energies of the electrons are increased compared to the energies in the free atoms'], 2,
   r'Band width $=4t$ in 1D ($E=E_0-2t\cos ka$), and the hopping $t$ is the overlap matrix element between neighbouring orbitals (script 3.2.3, sheet 7 Q3). Weakly bound (extended) orbitals overlap more: wider bands. Bands from different orbitals can overlap.'),
 q(8, 45, 'Pressure is applied to a simple cubic lattice: closer packing, same structure. In the tight-binding model, the energy bands ...', ['are raised in energy and become narrower', 'are raised in energy and become wider', 'are lowered in energy and become narrower', 'are lowered in energy and become wider'], 3,
   r'Closer atoms overlap more: $t$ grows, the band ($E_0\pm2t$ per direction) widens. The band centre drops too, because every orbital now feels more of its neighbours’ attractive potentials: in sheet 3 Q3, $E_0=\epsilon_0-V_0\kappa e^{-2\kappa d}$ falls as the distance $d$ shrinks.'),
 q(8, 46, r'According to Bloch’s theorem, which equality is correct? ($\vec R$: direct lattice vector, $\vec G$: reciprocal lattice vector)', [r'$\psi_{\vec k}(\vec r+\vec R)=\psi_{\vec k+\vec G}(\vec r)$', r'$\psi_{\vec k}(\vec r+\vec R)=\psi_{\vec k}(\vec r)$', r'$\psi_{\vec k-\vec G}(\vec r)=e^{i\vec k\cdot\vec R}\psi_{\vec k}(\vec r)$', r'$\psi_{\vec k}(\vec r+\vec R)=e^{i\vec k\cdot\vec R}\psi_{\vec k+\vec G}(\vec r)$'], 3,
   r'Bloch: $\psi_{\vec k}(\vec r)=e^{i\vec k\cdot\vec r}u_{\vec k}(\vec r)$ with lattice-periodic $u$, so $\psi_{\vec k}(\vec r+\vec R)=e^{i\vec k\cdot\vec R}\psi_{\vec k}(\vec r)$: only a phase, not full periodicity. And $\vec k$ is defined up to $\vec G$: $\psi_{\vec k+\vec G}=\psi_{\vec k}$ (script 3.2.1). Together they give the marked option.'),
]

QUIZZES = [
 ('lattice-gate', 'ss-lat-SQ1', 'Lecture questions: lattices and crystal structures', LATTICE, 'Week 1 (chapters 1.1–1.2)'),
 ('lattice-gate', 'ss-lat-SQ2', 'Lecture questions: the reciprocal lattice', RECIPROCAL, 'Week 2 and the week-8 quiz (chapter 1.3)'),
 ('lattice-gate', 'ss-lat-SQ3', 'Lecture questions: diffraction', DIFFRACTION, 'Week 2 and the week-8 quiz (chapter 1.5)'),
 ('bonding-grotto', 'ss-bon-SQ1', 'Lecture questions: bonding', BONDING, 'Week 3 and the week-8 quiz (chapter 1.6)'),
 ('phonon-halls', 'ss-pho-SQ1', 'Lecture questions: lattice dynamics', PHONONS, 'Week 4 and the week-8 quiz (chapter 2)'),
 ('fermi-sea', 'ss-fer-SQ1', 'Lecture questions: free electrons and specific heat', ELECTRONS, 'Week-8 quiz (chapter 3.1)'),
 ('fermi-sea', 'ss-fer-SQ2', 'Lecture questions: bands, Bloch, tight binding', BANDS, 'Week-8 quiz (chapters 3.2–3.3)'),
]
